def _call(name, args):
    return {"role": "assistant", "content": "", "tool_calls": [
        {"type": "function", "function": {"name": name, "arguments": args}}
    ]}


def _result(name, value):
    import json
    content = value if isinstance(value, str) else json.dumps(value, ensure_ascii=False)
    return {"role": "tool", "name": name, "content": content}


def tool_examples():
    """Training transcripts with exact runtime argument names and simulated outcomes."""
    examples = []

    def one(key, user, name, args, result, answer):
        examples.append((key, [{"role": "user", "content": user}, _call(name, args),
                               _result(name, result), {"role": "assistant", "content": answer}]))

